// ------------------------------------------------------------
// A6) NetImport(): net exchange with all neighbors
// ------------------------------------------------------------
.create-or-alter function with (folder = "Agent", docstring = "Net physical power exchange of Germany with all neighboring countries, 15-minute values in GW. Positive = net import, negative = net export. CountriesReported = how many of 11 countries had reported.")
NetImport() {
    let reported = energy_latest
        | where endpoint == "cbpf" and series_id != "sum"
        | summarize CountriesReported = countif(value != 0) by ts;
    energy_latest
    | where endpoint == "cbpf" and series_id == "sum"
    | join kind=inner reported on ts
    | project ts,
              Time_local = datetime_utc_to_local(ts, "Europe/Berlin"),
              NetImport_GW = round(value, 3),
              CountriesReported
}
